  return {
    width: decoded.width,
    height: decoded.height,
    directory,
    writes: pngs.map(({ png }, i) => ({ path: files[i]!, bytes: png })),
    frames: pngs.map(({ delayMs }, i) => ({ source: { file: files[i]!, format: 'png' }, delayMs })),
